# -*- coding: utf-8 -*-
"""Türkçe metin işlemleri: Türk kurallarıyla küçük/büyük harfe çevirme ve
Türk alfabesine göre sıralama."""

import re


def _is_tr_upper(c):
    """Karakter (Unicode normal biçimde) büyük bir Türkçe harfse True döner.
    I, İ ve A-Z arası Latin büyük harfleri için geçerli."""
    if c == "I" or c == "İ":
        return True
    lo = ord(c.lower())
    up = ord(c.upper())
    # Büyük bir harf: upper() kendisidir ve lower()'i farklıdır;
    # 0x0041..0x005A (A-Z) aralığı dışında kalan özel Latin büyükleri de kapsayalım.
    return c == c.upper() and lo != up


def _tr_lower_char(c):
    """Tek Türkçe harfi küçük yazar; diğerleri için normal lower()."""
    if "I" <= c <= "Z":  # I..Z -> i..z (Türkçe: I -> i)
        return chr(ord(c) + 32)
    if c == "İ":
        return "i"
    return c.lower()


def _tr_upper_char(c):
    """Tek Türkçe harfi büyük yazar; diğerleri için normal upper()."""
    lo = ord(c)
    if 0x69 <= lo <= 0x7A:  # i..z -> I..Z (Türkçe: i -> I)
        return chr(lo - 32)
    if c == "ı":
        return "I"
    return c.upper()


def tr_lower(s):
    """Verilen metni Türk kurallarıyla küçük harfe çevirir."""
    return "".join(_tr_lower_char(c) for c in s)


def tr_upper(s):
    """Verilen metni Türk kurallarıyla büyük harfe çevirir."""
    return "".join(_tr_upper_char(c) for c in s)


_TR_ALPHABET = "abcçdefgğhıijklmnoöpqrsştuüvwxyz"
_ORDER = {ch: i for i, ch in enumerate(_TR_ALPHABET)}
_DIGITS = set("0123456789")
_NON_BASIC = re.compile(r"[^a-zA-Z0-9]")


def _key(w):
    """Sıralama anahtarı: her karakter (tip, kod noktası / alfabe indeksi) çifti.

    - Boşluk ve noktalama vb. temel harf/rakam dışındaki karakterler "önce" gelir;
      kendi aralarında Unicode kod noktasına göre sıralanır.
    - Rakamlar Türk alfabesindeki yeriyle (abc'den önce, 'a'nın yerine) gelir:
      0123456789abc...
    - Harfler Türkçe kurallarla küçültülüp alfabe indeksleriyle karşılaştırılır."""
    key = []
    for c in w:
        if _NON_BASIC.match(c):
            # Önce gelen grup; kendi içinde kod noktası sıralı.
            key.append((0, ord(c)))
        elif c.isdigit():
            key.append((1, int(c)))
        else:
            ch = _tr_lower_char(c) if c.isupper() else c.lower()
            idx = _ORDER.get(ch)
            if idx is not None:
                key.append((2, idx))
            else:  # beklenmeyen harf; kod noktasına göre alfabe sonuna ekle
                key.append((3, ord(c)))
    return tuple(key)


def tr_sorted(words):
    """Kelimeleri Türk alfabesine göre büyük/küçük harf farkı gözetmeden sıralar.

    Girdi listesi değiştirilmez; yeni bir liste döner. Eşit sayılan kelimeler
    girdideki sıralarını korur (kararlı sıralama)."""
    return [w for _, w in sorted(enumerate(words), key=lambda p: _key(p[1]))]

